import runpy,json,torch,hashlib,math
from pathlib import Path
from copy import deepcopy
from types import SimpleNamespace
api=runpy.run_path('/ml2/hypergan/ParticleGAN-pr155-merge/examples/e22_routed_sites.py')
torch.set_num_threads(1)
loop=api['make_loop'](mode='full',initialization='conformance',device='cuda:1',tokens=128,z_dim=4,particles=128,batch_size=8)
p=loop.policy;c=p.routed_control;original=c._commit
moves=[]
@torch.no_grad()
def state():
    return {'sigma':p.output_sigma(),'log_sigma':float(p.log_output_sigma),'controller':p.controller.diagnostics(),'table_std':p.table.std(0,unbiased=False).tolist(),'table_min':p.table.min(0).values.tolist(),'table_max':p.table.max(0).values.tolist(),'mass_min':float(p.router.log_mass.min()),'mass_max':float(p.router.log_mass.max()),'stationarity':[dict(role=role,s=t.s,b=t.b,tau=t.tau,counts=dict(t.counts)) for opt,ts,rs in zip(p.optimizers,p.lr_settle.testers,p.roles) for g,t,role in zip(opt.param_groups,ts,rs) if t is not None]}
@torch.no_grad()
def forward_metric(context,target,candidate, *, support_table=None, future_bandwidth=False):
    applications=[]
    ctrl=p.controller if not future_bandwidth else deepcopy(p.controller)
    if future_bandwidth:ctrl.observe_prior(SimpleNamespace(z=support_table))
    stream=torch.Generator(device=p.device).manual_seed(99)
    prior=SimpleNamespace(z=support_table)
    def perturb(codes):
        out=ctrl.perturb_latent(codes,stream,prior,record=False)
        applications.append({'code_mean':codes.mean(0).tolist(),'code_std':codes.std(0,unbiased=False).tolist(),'jitter_rms':float((out-codes).square().mean().sqrt()),'jitter_max_norm':float((out-codes).norm(dim=1).max())})
        return out
    out=c.generate(context,candidate=candidate,perturb_fn=None if support_table is None else perturb)
    residual=(out-target)/p.D.scale
    f=c.spec.features(c.models,context,out,target)
    reference=c.spec.features(c.models,context,target,target)
    feature=(f.double()-reference.double()).square().mean(1)
    percontext=(out.double()-target.double()).square().flatten(1).mean(1)
    return out,{'rmse':float(percontext.mean().sqrt()),'mse':float(percontext.mean()),'max_context_mse':float(percontext.max()),'normalized_rmse':float(residual.square().mean().sqrt()),'feature_error':float(feature.mean()),'applications':applications}
@torch.no_grad()
def instrument(child,parent,proposed,average):
    base=c.candidate(copy=True)
    pools={'fit':(c.fit_context[:c.fit_fill],c.fit_targets[:c.fit_fill]),'guard':(c.guard_context[:c.guard_fill],c.guard_targets[:c.guard_fill]),'test':(loop.test_context,loop.test_targets)}
    record={'step':p.completed_steps+1,'child':child,'parent':parent,'variant':c.last['variant'],'state_before':state(),'metrics':{},'guard_event':deepcopy(c.last)}
    for name,(ctx,target) in pools.items():
        outputs={};metrics={}
        for label,cand,support,future in [('clean_before',base,None,False),('clean_after',proposed,None,False),('noisy_before',base,base.table,False),('noisy_after',proposed,proposed.table,False),('same_clean_codes_new_support',base,proposed.table,False),('new_codes_old_support',proposed,base.table,False),('next_bandwidth_before',base,base.table,True),('next_bandwidth_after',proposed,proposed.table,True)]:
            outputs[label],metrics[label]=forward_metric(ctx,target,cand,support_table=support,future_bandwidth=future)
        metrics['same_noise_output_differences']={name:float((outputs[name]-outputs['noisy_before']).square().mean().sqrt()) for name in ['noisy_after','same_clean_codes_new_support','new_codes_old_support']}
        record['metrics'][name]=metrics
    original(child,parent,proposed,average)
    record['state_after_commit']=state()
    moves.append(record)
    print(json.dumps({'event':'accepted_move','step':record['step'],'child':child,'parent':parent,'variant':record['variant'],'guard':record['metrics']['guard'],'test':record['metrics']['test']}),flush=True)
c._commit=instrument
api['warmup'](loop,1);moves.clear()
trajectory=[];traces=[]
for i in range(40):
    state_before=state()
    with torch.autograd.set_multithreading_enabled(False): row=api['update'](loop)
    with torch.no_grad(),c._evaluating():
        out,metric=forward_metric(loop.test_context,loop.test_targets,c.candidate(copy=True))
    trajectory.append({'step':i+1,'metric':metric,'state_before':state_before,'state_after':state(),'loss_g':row['loss_g'],'loss_d':row['loss_d'],'move':row['move']})
    traces.append((row['batch_indices'],row['base_noise_sums'],row['paired_rng_digest'],row['dv12_rng_digest']))
    if (i+1)%10==0:print(json.dumps({'event':'update','step':i+1,'rmse':metric['rmse'],'sigma':p.output_sigma()}),flush=True)
report={'source_revision':'03e6d705e2c386dada82b4df46c742483c0837c7','device':str(p.device),'config':loop.config,'moves':moves,'trajectory':trajectory,'final':api['evaluate'](loop),'diagnostics':api['diagnostics'](p),'matched_inputs_trace_sha256':hashlib.sha256(json.dumps(traces).encode()).hexdigest()}
Path('/tmp/e22_current_move_instrument.json').write_text(json.dumps(report,indent=2))
print(json.dumps({'event':'complete','final':report['final'],'moves':len(moves),'receipt':'/tmp/e22_current_move_instrument.json'}),flush=True)

