import runpy,torch,json,hashlib,subprocess,math,io
from pathlib import Path
from copy import deepcopy
from torch import nn
api=runpy.run_path('/ml2/hypergan/ParticleGAN-pr155-merge/examples/e22_routed_sites.py')
torch.set_num_threads(1)
class TokenPenaltyView(nn.Module):
 def __init__(self,critic,tokens):
  super().__init__();self.critic=critic;self.tokens=tokens
 def forward(self,flat):
  assert flat.ndim==2 and len(flat)%self.tokens==0
  batch=len(flat)//self.tokens
  score=self.critic(flat.reshape(batch,self.tokens,flat.shape[-1]))
  assert score.shape==(batch,1)
  return score[:,None,:].expand(batch,self.tokens,1).reshape(-1,1)
class TokenLocalPenalty:
 def __init__(self,base,view):self.base,self.view=base,view
 def __getattr__(self,name):return getattr(self.base,name)
 def __call__(self,critic,real,fake):
  assert critic is self.view.critic and real.shape==fake.shape and real.ndim==3
  return self.base(self.view,real.flatten(0,1),fake.flatten(0,1))
def same(a,b):
 if isinstance(a,torch.Tensor):torch.testing.assert_close(a,b,rtol=0,atol=0,equal_nan=True)
 elif isinstance(a,dict):
  assert a.keys()==b.keys()
  for k in a:same(a[k],b[k])
 elif isinstance(a,(list,tuple)):
  assert type(a) is type(b) and len(a)==len(b)
  for x,y in zip(a,b):same(x,y)
 elif isinstance(a,float) and math.isnan(a):assert math.isnan(b)
 else:assert a==b,(a,b)
def cpu_roundtrip(x):
 buff=io.BytesIO();torch.save(x,buff);buff.seek(0)
 return torch.load(buff,map_location='cpu',weights_only=True)
# Phase fixtures isolate both gradients and nonzero blended anchor/cap terms.
phase_receipts=[]
for phase in ['a','blend']:
 reference=None
 for tokens in [1,8,128]:
  D=api['TokenErrorCritic'](torch.tensor([.04,.04])).double()
  api['init'].deterministic_orthogonal_(D.features,seed=5);api['init'].deterministic_orthogonal_(D.score,seed=6)
  with torch.no_grad():D.score.weight.mul_(8.)
  recipe=api['get_recipe']('e22_routed',num_particles=16,z_dim=2,batch_size=4,output_noise_std=.125)
  opt=recipe.make_critic_optimizer(D,ema_critic=deepcopy(D),foreach=False)
  penalty=recipe.make_critic_penalty(opt,collect_stats=True)
  # Complete one real critic update, then select a kernel phase for this unit witness.
  opt.zero_grad();sum(p.square().sum()*0 for p in D.parameters()).backward();opt.step()
  if phase=='blend':
   opt.record.calls=799;opt.record.anchor_started=True
   opt.anchor.start_()
   with torch.no_grad():
    for parameter in opt.ema_critic.parameters():parameter.mul_(.8)
  view=TokenPenaltyView(D,tokens)
  real=torch.tensor([[.05,-.1],[-.04,.02],[.1,.07],[-.03,-.08]],dtype=torch.float64)[:,None].expand(-1,tokens,-1).clone()
  fake=real+.2
  value=penalty(view,real.flatten(0,1),fake.flatten(0,1))
  opt.zero_grad();value.backward()
  gradient=torch.cat([p.grad.flatten() for p in D.parameters() if p.grad is not None])
  score=D(real).detach()
  if reference is None:reference=(value.detach().clone(),gradient.clone(),score.clone())
  differences={'penalty':float(abs(value.detach()-reference[0])),'parameter_gradient_max':float((gradient-reference[1]).abs().max()),'score_max':float((score-reference[2]).abs().max())}
  torch.testing.assert_close(value.detach(),reference[0],rtol=2e-12,atol=2e-12)
  torch.testing.assert_close(gradient,reference[1],rtol=2e-12,atol=2e-12)
  torch.testing.assert_close(score,reference[2],rtol=2e-12,atol=2e-12)
  phase_receipts.append({'phase':phase,'tokens':tokens,'penalty':float(value.detach()),'stats':penalty.last_stats,'differences_from_single_token':differences})
 print(json.dumps({'event':'cpu_phase_checked','phase':phase,'tokens':[1,8,128]}),flush=True)
# Lazy skips do not advance phase clock; a lazy active call has exactly K scaling.
D=api['TokenErrorCritic'](torch.tensor([.04,.04])).double()
api['init'].deterministic_orthogonal_(D.features,seed=5);api['init'].deterministic_orthogonal_(D.score,seed=6)
recipe=api['get_recipe']('e22_routed',num_particles=16,z_dim=2,batch_size=4,output_noise_std=.125)
opt=recipe.make_critic_optimizer(D,ema_critic=deepcopy(D),foreach=False)
penalty=recipe.make_critic_penalty(opt,lazy_k=3,collect_stats=True)
view=TokenPenaltyView(D,8)
real=torch.zeros(4,8,2,dtype=torch.float64);fake=real+.2
lazy=[]
for i in range(3):
 val=penalty(view,real.flatten(0,1),fake.flatten(0,1));lazy.append({'step':i+1,'penalty':float(val.detach()),'calls':opt.record.calls,'stats':penalty.last_stats.copy()})
 opt.zero_grad();sum(p.square().sum()*0 for p in D.parameters()).backward();opt.step()
assert [x['calls'] for x in lazy]==[0,0,1]
refopt=recipe.make_critic_optimizer(deepcopy(D),ema_critic=deepcopy(D),foreach=False)
refpen=recipe.make_critic_penalty(refopt,lazy_k=1)
refvalue=refpen(TokenPenaltyView(refopt.critic,8),real.flatten(0,1),fake.flatten(0,1))
assert abs(lazy[-1]['penalty']-3*float(refvalue.detach()))<1e-12
print(json.dumps({'event':'cpu_lazy_checked','receipt':lazy}),flush=True)
results=[]
for initialization in ['conformance','api']:
 reference_inputs=None
 for mode in ['no_rows','full']:
  def build():
   loop=api['make_loop'](mode=mode,initialization=initialization,device='cuda:1',tokens=128,z_dim=4,particles=128,batch_size=8)
   loop.config['penalty_units']='token_local_existing_api_view'
   p=loop.policy
   p.penalty=TokenLocalPenalty(p.penalty,TokenPenaltyView(p.D,128))
   metrics=[];reg=p.penalty.regularizer;raw=reg._grad_norm
   def record_norm(D,x,squared=False):
    out=raw(D,x,squared=squared)
    if not squared:metrics.append({'fake_local_rms_max':float((out/2**.5).max().detach()),'fake_local_cap_max':float((out/2**.5-reg.kappa).relu().square().max().detach()),'fake_local_cap_mean':float((out/2**.5-reg.kappa).relu().square().mean().detach())})
    return out
   reg._grad_norm=record_norm
   return loop,metrics
  loop,metrics=build();api['warmup'](loop,1);metrics.clear()
  rows=[];inputs=[];trajectory=[];saved=None
  for i in range(120):
   with torch.autograd.set_multithreading_enabled(False):row=api['update'](loop)
   rows.append(row);inputs.append((row['batch_indices'],row['base_noise_sums'],row['paired_rng_digest'],row['dv12_rng_digest']))
   if (i+1)%5==0:trajectory.append({'step':i+1,**api['evaluate'](loop),'splits':loop.policy.routed_control.counters['splits']})
   if i==59 and mode=='full':saved=cpu_roundtrip(api['checkpoint'](loop))
   if (i+1)%40==0:print(json.dumps({'event':'checkpoint','initialization':initialization,'mode':mode,**trajectory[-1]}),flush=True)
  if reference_inputs is None:reference_inputs=inputs
  else:assert inputs==reference_inputs
  recovered=False
  if mode=='full':
   final=api['checkpoint'](loop)
   restored,resume_metrics=build();api['restore'](restored,saved)
   for row in rows[60:]:
    with torch.autograd.set_multithreading_enabled(False):same(row,api['update'](restored))
   same(final,api['checkpoint'](restored));same(loop.policy.served_model().routed_forward(loop.test_context),restored.policy.served_model().routed_forward(restored.test_context));recovered=True
  result={'initialization':initialization,'mode':mode,'final':api['evaluate'](loop),'trajectory':trajectory,'row_diagnostics':api['diagnostics'](loop.policy),'fake_cap_metrics':metrics,'fake_local_cap_active_updates':sum(x['fake_local_cap_max']>0 for x in metrics),'exact_checkpoint_resume_step60_to120':recovered if mode=='full' else None,'matched_inputs_sha256':hashlib.sha256(json.dumps(inputs).encode()).hexdigest()}
  results.append(result)
  Path('/tmp/e22_token_penalty_view_validation.partial.json').write_text(json.dumps(results,indent=2))
  print(json.dumps({'event':'arm_complete','initialization':initialization,'mode':mode,'final':result['final'],'fake_local_cap_active_updates':result['fake_local_cap_active_updates'],'exact_resume':result['exact_checkpoint_resume_step60_to120']}),flush=True)
root=Path('/ml2/hypergan/ParticleGAN-pr155-merge')
paths=sorted(root.glob('particlegan/**/*.py'))+[root/'examples/e22_routed_sites.py']
report={'source_revision':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'source_sha256':{str(path.relative_to(root)):hashlib.sha256(path.read_bytes()).hexdigest() for path in paths},'device':'cuda:1','torch_version':torch.__version__,'hardware':'NVIDIA RTX A6000','harness':Path(__file__).read_text(),'cpu_phase_fixtures':phase_receipts,'cpu_lazy_fixture':lazy,'training_results':results,'interpretation':'Dedicated existing-API penalty view preserves pooled critic scores for the game and original context grouping; only penalty derivatives use token-local gradient units. A/B/EMA-prox parameter-gradient invariance tested on replicated tokens; phase fixture selects clock position, training runs remain pure-A120.'}
Path('/tmp/e22_token_penalty_view_validation.json').write_text(json.dumps(report,indent=2))
print(json.dumps({'event':'complete','receipt':'/tmp/e22_token_penalty_view_validation.json'}),flush=True)
